import{_ as t,o as a,c as l,ap as o}from"./chunks/framework.BSEl3JtH.js";const m=JSON.parse('{"title":"Developers","description":"","frontmatter":{},"headers":[],"relativePath":"developers.md","filePath":"developers.md","lastUpdated":null}'),s={name:"developers.md"};function r(n,e,i,d,h,c){return a(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers {#developers}&quot;">​</a></h1><p>How the collection is built, tested and documented. The procedures live next to the code they describe, in READMEs, so that they change with it; this page says where to find them.</p><h2 id="The-principle" tabindex="-1">The principle <a class="header-anchor" href="#The-principle" aria-label="Permalink to &quot;The principle {#The-principle}&quot;">​</a></h2><p><strong>What can be computed is generated or checked, never maintained by hand.</strong> The availability of a problem in a modeling is the presence of its file; the features are computed from the model; the reference objectives from the results of the crons; the documentation pages from the files of each problem. A test checks that no list of problems is written by hand.</p><h2 id="Where-to-read" tabindex="-1">Where to read <a class="header-anchor" href="#Where-to-read" aria-label="Permalink to &quot;Where to read {#Where-to-read}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">I want to</th><th style="text-align:left;">Read</th></tr></thead><tbody><tr><td style="text-align:left;">add a problem, or a modeling</td><td style="text-align:left;"><a href="https://github.com/control-toolbox/OptimalControlProblems.jl/blob/main/ext/README.md" target="_blank" rel="noreferrer"><code>ext/README.md</code></a></td></tr><tr><td style="text-align:left;">run the tests, or add one</td><td style="text-align:left;"><a href="https://github.com/control-toolbox/OptimalControlProblems.jl/blob/main/test/README.md" target="_blank" rel="noreferrer"><code>test/README.md</code></a></td></tr><tr><td style="text-align:left;">know what the crons do, and handle the issues they open</td><td style="text-align:left;"><a href="https://github.com/control-toolbox/OptimalControlProblems.jl/blob/main/.github/workflows/README.md" target="_blank" rel="noreferrer"><code>.github/workflows/README.md</code></a></td></tr><tr><td style="text-align:left;">compute the reference objectives again</td><td style="text-align:left;"><a href="https://github.com/control-toolbox/OptimalControlProblems.jl/blob/main/tools/references/README.md" target="_blank" rel="noreferrer"><code>tools/references/README.md</code></a></td></tr><tr><td style="text-align:left;">know the NLP of each JuMP scheme</td><td style="text-align:left;"><a href="/OptimalControlProblems.jl/previews/PR411/guide/jump-schemes#jump-schemes">JuMP schemes</a></td></tr><tr><td style="text-align:left;">follow the conventions of the ecosystem</td><td style="text-align:left;"><a href="https://github.com/control-toolbox/ct-conventions" target="_blank" rel="noreferrer">ct-conventions</a> and <code>AGENTS.md</code></td></tr></tbody></table><h2 id="Three-kinds-of-tests" tabindex="-1">Three kinds of tests <a class="header-anchor" href="#Three-kinds-of-tests" aria-label="Permalink to &quot;Three kinds of tests {#Three-kinds-of-tests}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Kind</th><th style="text-align:left;">When</th><th style="text-align:left;">Fails on</th></tr></thead><tbody><tr><td style="text-align:left;">Does not break</td><td style="text-align:left;">every pull request, small grid, a few iterations</td><td style="text-align:left;">an exception or a non-finite objective</td></tr><tr><td style="text-align:left;">Same NLP</td><td style="text-align:left;">every pull request, no solve</td><td style="text-align:left;">two modelings that give different NLPs</td></tr><tr><td style="text-align:left;">Convergence</td><td style="text-align:left;">the weekly crons, or on demand (label <code>test convergence</code>)</td><td style="text-align:left;">nothing: the solver status and the gap to the reference are reported</td></tr></tbody></table><p>The convergence results feed the reference objectives and the problem pages, and the <a href="/OptimalControlProblems.jl/previews/PR411/problems-status#problems-status">Status</a> page shows the latest reports.</p><h2 id="The-documentation" tabindex="-1">The documentation <a class="header-anchor" href="#The-documentation" aria-label="Permalink to &quot;The documentation {#The-documentation}&quot;">​</a></h2><p>The problem pages, the Status page and the API Reference are generated at each build; <code>docs/modelings.jl</code> holds what the pages need to know about each modeling. The build solves nothing for the problem pages: their results come from the crons. To build it locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/build/1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5173</span></span></code></pre></div>`,12)])])}const f=t(s,[["render",r]]);export{m as __pageData,f as default};
